import { Contract, GlobalState, abimethod, uint64, Txn, Global, Uint64, Bytes, assert, Account, itxn, gtxn, clone } from '@algorandfoundation/algorand-typescript'

export class JokePayPerCall extends Contract {
  // Service configuration
  owner = GlobalState<Account>({ key: 'o' })
  pricePerCall = GlobalState<uint64>({ key: 'p' }) // in microUSDC (6 decimals)
  totalJokesServed = GlobalState<uint64>({ key: 'tc' })
  totalEarned = GlobalState<uint64>({ key: 'te' })

  public createApplication(): void {
    this.owner.value = Txn.sender
    this.pricePerCall.value = Uint64(5000) // 0.005 USDC
    this.totalJokesServed.value = Uint64(0)
    this.totalEarned.value = Uint64(0)
  }

  /**
   * record_payment — TRUSTLESS payment verification for x402.
   * Verifies that a real AssetTransfer (USDC) exists in the atomic group.
   * Facilitator groups: [0] AssetTransferTxn, [1] AppCall (record_payment)
   */
  @abimethod()
  public record_payment(): void {
    // Verify an AssetTransfer transaction exists in this atomic group at index 0
    const payment = gtxn.AssetTransferTxn(Uint64(0))

    // Verify payment goes to the contract account
    assert(
      payment.assetReceiver === Global.currentApplicationAddress,
      'Payment must be sent to the contract'
    )

    // Verify payment amount meets the price requirement
    const amount: uint64 = payment.assetAmount
    assert(amount >= this.pricePerCall.value, 'Payment below minimum price')

    // Update accounting and stats
    this.totalJokesServed.value = this.totalJokesServed.value + Uint64(1)
    this.totalEarned.value = this.totalEarned.value + amount
  }

  @abimethod()
  public set_price(newPrice: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can set price')
    this.pricePerCall.value = newPrice
  }

  @abimethod()
  public get_stats(): uint64 {
    return this.totalJokesServed.value
  }

  @abimethod()
  public withdraw(assetId: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can withdraw')

    const balance: uint64 = this.totalEarned.value
    assert(balance > Uint64(0), 'Nothing to withdraw')

    // Send accumulated USDC earnings to owner
    itxn.assetTransfer({
      xferAsset: assetId,
      assetReceiver: this.owner.value,
      assetAmount: balance,
      fee: Uint64(0),
    }).submit()

    // Reset earnings counter after successful transfer
    this.totalEarned.value = Uint64(0)
  }

  /**
   * opt_in_to_asset — Required for the contract to receive USDC
   */
  @abimethod()
  public opt_in_to_asset(assetId: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can opt-in contract to assets')
    itxn.assetTransfer({
      xferAsset: assetId,
      assetReceiver: Global.currentApplicationAddress,
      assetAmount: Uint64(0),
      fee: Uint64(0),
    }).submit()
  }
}

